import React, { useState } from 'react';
import AuthModal from '/AuthModal';


const AuthButtons = () => {
    // Временный стейт для проверки залогинен ли пользователь
    const [authModalType, setAuthModalType] = useState(null); // 'signin' или 'signup'

    const openModal = (type) => setAuthModalType(type);
    const closeModal = () => setAuthModalType(null);

    // Функции-заглушки (потом заменишь на реальные API вызовы)
    const handleLogin = () => {
        console.log('Переход на страницу логина');
        // Здесь будет вызов API или переход на страницу логина
    };

    const handleSignUp = () => {
        console.log('Переход на страницу регистрации');
        // Здесь будет вызов API или переход на страницу регистрации
    };

    return (
        <div className="auth-buttons">
                <div className="auth-buttons-container">
                    <button onClick={() => openModal('signin')} className="login-btn">
                        Log In
                    </button>
                    <button onClick={() => openModal('signup')} className="signup-btn">
                        Sign Up
                    </button>
                </div>
        </div>
    );
};

export default AuthButtons;
